package com.iare.club.service;
import com.fasterxml.jackson.databind.*;import com.iare.club.repository.*;import com.iare.club.entity.*;import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentWebhookService{
 private final PaymentWebhookDeliveryRepository deliveries;private final PaymentDetectionEventRepository detections;private final UpiPaymentService payments;private final ObjectMapper json;private final Clock clock;private final String youpiSecret;private final String authorizedSecret;
 public PaymentWebhookService(PaymentWebhookDeliveryRepository d,PaymentDetectionEventRepository detections,UpiPaymentService p,ObjectMapper j,Clock c,@Value("${payments.verification.youpi.webhook-secret:}")String ys,@Value("${payments.verification.authorized-provider.webhook-secret:}")String as){deliveries=d;this.detections=detections;payments=p;json=j;clock=c;youpiSecret=ys;authorizedSecret=as;}
 @Transactional public void youpi(byte[] raw,String signature,String signatureV2,String timestamp,String deliveryId){requireSignature(raw,signature,signatureV2,timestamp,youpiSecret);JsonNode n=read(raw);String id=required(deliveryId,"delivery id");if(deliveries.existsByProviderAndDeliveryId("YOUPI",id))return;String ref=text(n,"orderId"),event=text(n,"event"),settlement=text(n,"settlementState");BigDecimal amount=parseAmount(text(n,"amount"));try{payments.applyYoupiOutcome(ref,text(n,"paymentId"),text(n,"utr"),event,settlement);detections.save(new PaymentDetectionEvent(ref,"YOUPI",id,event,amount,text(n,"utr"),settlement,true,"Signed YouPI lifecycle event",clock.instant()));deliveries.save(new PaymentWebhookDelivery("YOUPI",id,ref,event,true,"Authenticated YouPI event",clock.instant()));}catch(DepositService.FinancialException e){detections.save(new PaymentDetectionEvent(ref,"YOUPI",id,event,amount,text(n,"utr"),settlement,false,e.getMessage(),clock.instant()));deliveries.save(new PaymentWebhookDelivery("YOUPI",id,ref,event,false,e.getMessage(),clock.instant()));}}
 @Transactional public void authorized(byte[] raw,String signature,String signatureV2,String timestamp,String deliveryId){requireSignature(raw,signature,signatureV2,timestamp,authorizedSecret);JsonNode n=read(raw);String id=required(deliveryId,"delivery id");if(deliveries.existsByProviderAndDeliveryId("AUTHORIZED_PROVIDER",id))return;if(!"PAYMENT_VERIFIED".equals(text(n,"event")))throw new DepositService.FinancialException("Unsupported provider event");String ref=text(n,"reference");payments.authorizedVerify(ref,new BigDecimal(text(n,"amount")),text(n,"transactionId"),text(n,"utr"),text(n,"merchantUpiId"));deliveries.save(new PaymentWebhookDelivery("AUTHORIZED_PROVIDER",id,ref,text(n,"event"),true,"Authenticated verification accepted",clock.instant()));}
 private void requireSignature(byte[] raw,String sig,String sigV2,String timestamp,String secret){if(secret==null||secret.isBlank())throw new DepositService.FinancialException("Webhook provider is not configured");String expected="sha256="+hmac(secret,raw);boolean valid=MessageDigest.isEqual(expected.getBytes(StandardCharsets.US_ASCII),(sig==null?"":sig).getBytes(StandardCharsets.US_ASCII));if(timestamp!=null&&!timestamp.isBlank()&&sigV2!=null&&!sigV2.isBlank()){long sent=Long.parseLong(timestamp);if(Math.abs(clock.millis()-sent)>Duration.ofMinutes(65).toMillis())throw new DepositService.FinancialException("Webhook timestamp outside retry window");byte[] bound=(timestamp+"."+new String(raw,StandardCharsets.UTF_8)).getBytes(StandardCharsets.UTF_8);String expectedV2="sha256="+hmac(secret,bound);valid&=MessageDigest.isEqual(expectedV2.getBytes(StandardCharsets.US_ASCII),sigV2.getBytes(StandardCharsets.US_ASCII));}if(!valid)throw new DepositService.FinancialException("Invalid webhook signature");}
 private static String hmac(String secret,byte[] body){try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return java.util.HexFormat.of().formatHex(mac.doFinal(body));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
 private JsonNode read(byte[] raw){try{return json.readTree(raw);}catch(Exception e){throw new DepositService.FinancialException("Invalid webhook JSON");}}private static String text(JsonNode n,String name){JsonNode v=n.get(name);return v==null?null:v.asText();}private static String required(String value,String label){if(value==null||value.isBlank())throw new DepositService.FinancialException("Missing "+label);return value;}
 private static BigDecimal parseAmount(String value){try{return value==null?null:new BigDecimal(value);}catch(NumberFormatException e){return null;}}
}
